package ace

import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"math/rand";"os";"os/exec";"path/filepath";"strconv";"strings";"testing";"time")

type aoProposal struct{ID,Representation,Semantics,Terminal,Reason,Signature string `json:"id,omitempty" json:"representation,omitempty" json:"semantics,omitempty" json:"terminal_classification,omitempty" json:"reason,omitempty" json:"behavioral_signature,omitempty"`}
type aoCondition struct{Name string `json:"name"`;Proposals []aoProposal `json:"proposals"`;Installed string `json:"installed_operator"`;FutureSearchExposed bool `json:"future_search_exposed"`;HeldOut bool `json:"heldout_pass"`;CandidateCount,BudgetUsed int `json:"candidate_count" json:"budget_used"`}
type aoReport struct{Head,Parent string;GitStatus,ExperimentCommit,RuntimeTimestamp,WorkflowRunID string;ProvenanceMatch bool `json:"provenance_match"`;Target string `json:"external_heldout_target"`;GapDiagnosis map[string]any `json:"capability_gap_diagnosis"`;Conditions []aoCondition `json:"conditions"`;NoveltyRule map[string]any `json:"semantic_novelty_rule"`;IndependentVerification map[string]any `json:"independent_verification"`;Controls map[string]any `json:"controls"`;Answers map[string]any `json:"answers"`;FinalClassification string `json:"final_classification"`;ExactBoundary string `json:"exact_boundary"`}

func aoProv(t *testing.T)(string,string,string,string,bool){run:=func(a ...string)string{c:=exec.Command("git",a...);b,e:=c.Output();if e!=nil{t.Fatalf("provenance unavailable: git %s: %v",strings.Join(a," "),e)};return strings.TrimSpace(string(b))};h:=run("rev-parse","HEAD");p:=run("rev-parse","HEAD^");c:=exec.Command("git","status","--porcelain");b,e:=c.Output();if e!=nil{t.Fatalf("provenance unavailable: git status: %v",e)};exp:=strings.TrimSpace(os.Getenv("GITHUB_SHA"));m:=exp==""||exp==h;if h==""||p==""||!m{t.Fatalf("fail-closed provenance: head=%q parent=%q github_sha=%q match=%t",h,p,exp,m)};return h,p,string(b),os.Getenv("GITHUB_RUN_ID"),m}

// Independent reference interpreter: deliberately does not call UniversalProgram.Run.
func aoRef(p UniversalProgram,in map[string]string)(map[string]string,error){env:=map[string]string{};for k,v:=range in{env[k]=v};var ex func(*UExpr)(int,error);ex=func(x *UExpr)(int,error){if x==nil{return 0,fmt.Errorf("nil expression")};switch x.Kind{case"const":return strconv.Atoi(x.Value);case"var":v,ok:=env[x.Value];if !ok{return 0,fmt.Errorf("missing variable")};return strconv.Atoi(v);case"add","sub","mul","lt","eq","and","or":a,e:=ex(x.Left);if e!=nil{return 0,e};b,e:=ex(x.Right);if e!=nil{return 0,e};switch x.Kind{case"add":return a+b,nil;case"sub":return a-b,nil;case"mul":return a*b,nil;case"lt":if a<b{return 1,nil};return 0,nil;case"eq":if a==b{return 1,nil};return 0,nil;case"and":if a!=0&&b!=0{return 1,nil};return 0,nil;default:if a!=0||b!=0{return 1,nil};return 0,nil};case"not":a,e:=ex(x.Left);if e!=nil{return 0,e};if a==0{return 1,nil};return 0,nil};return 0,fmt.Errorf("unknown expression")};steps:=0;var st func([]UStmt)error;st=func(ss []UStmt)error{for _,s:=range ss{steps++;if steps>1000{return fmt.Errorf("step limit")};switch s.Kind{case"assign":n,e:=ex(s.Expr);if e!=nil{return e};env[s.Target]=strconv.Itoa(n);case"if":n,e:=ex(s.Cond);if e!=nil{return e};if n!=0{if e=st(s.Then);e!=nil{return e}}else{if e=st(s.Else);e!=nil{return e}};case"repeat":if s.Count<0||s.Count>100{return fmt.Errorf("invalid repeat")};for i:=0;i<s.Count;i++{if e:=st(s.Body);e!=nil{return e}};default:return fmt.Errorf("unknown statement")}};return nil};if e:=st(p.Statements);e!=nil{return nil,e};return env,nil}

func aoSig(t *testing.T,c vfCandidate)string{var p UniversalProgram;if c.Semantics=="UNBUILDABLE"||json.Unmarshal([]byte(c.Semantics),&p)!=nil{return "unexecutable"};h:=sha256.New();for _,n:=range []int{-23,-17,-11,-9,-5,-3,-1,0,1,2,3,5,8,13,17,21,29}{in:=map[string]string{"x":strconv.Itoa(n)};o,e:=aoRef(p,in);fmt.Fprintf(h,"%d:%s:%t;",n,o["y"],e==nil)};return hex.EncodeToString(h.Sum(nil))}
func aoVerify(t *testing.T,c vfCandidate,cases []ProgramTestCase)bool{var p UniversalProgram;if c.Semantics=="UNBUILDABLE"||json.Unmarshal([]byte(c.Semantics),&p)!=nil{return false};for _,tc:=range cases{o,e:=aoRef(p,tc.Input);if e!=nil{return false};for k,w:=range tc.Expected{if o[k]!=w{return false}}};return true}
func aoExamples()[]ProgramTestCase{return []ProgramTestCase{{Input:map[string]string{"x":"-8"},Expected:map[string]string{"y":"-4"}},{Input:map[string]string{"x":"-4"},Expected:map[string]string{"y":"-2"}},{Input:map[string]string{"x":"0"},Expected:map[string]string{"y":"0"}},{Input:map[string]string{"x":"2"},Expected:map[string]string{"y":"1"}},{Input:map[string]string{"x":"6"},Expected:map[string]string{"y":"3"}}}}
func aoTarget()[]ProgramTestCase{return []ProgramTestCase{{Input:map[string]string{"x":"-9"},Expected:map[string]string{"y":"-5"}},{Input:map[string]string{"x":"-3"},Expected:map[string]string{"y":"-2"}},{Input:map[string]string{"x":"-1"},Expected:map[string]string{"y":"-1"}},{Input:map[string]string{"x":"0"},Expected:map[string]string{"y":"0"}},{Input:map[string]string{"x":"1"},Expected:map[string]string{"y":"0"}},{Input:map[string]string{"x":"3"},Expected:map[string]string{"y":"1"}},{Input:map[string]string{"x":"8"},Expected:map[string]string{"y":"4"}},{Input:map[string]string{"x":"17"},Expected:map[string]string{"y":"8"}}}}
func aoSpec(t *testing.T)CapabilitySpecification{s,e:=GeneralCapabilitySpecification(Task{ID:"autonomous-discovery-gap",Goal:"infer the deterministic mapping supported by the observed examples",Structure:[]string{"scalar","mapping"},Budget:ResourceVector{Compute:100,Memory:100,TimeMS:5000,ExperimentBudget:20}},aoExamples());if e!=nil{t.Fatal(e)};return s}
func aoBase(t *testing.T,s CapabilitySpecification)[]vfCandidate{ms,e:=(UniversalMechanismSearch{}).SearchMechanisms(s,s.ResourceLimits);if e!=nil{t.Fatal(e)};out:=make([]vfCandidate,0,len(ms));for _,m:=range ms{p,e:=(UniversalProgramBuilder{}).Build(m,s);sem:="UNBUILDABLE";if e==nil{sem=p.Artifact};out=append(out,vfCandidate{ID:m.ID,Operator:m.Mechanism,Semantics:sem,Provenance:map[string]string{"source":"frozen-baseline-acquisition-language"}})};return out}

// The proposer has no special knowledge of the external evaluation target. It only packages
// executable hypotheses produced by the frozen acquisition language and must pass the novelty gate.
func aoPropose(t *testing.T,base []vfCandidate,probes []ProgramTestCase)[]aoProposal{baseS:=map[string]bool{};for _,c:=range base{baseS[aoSig(t,c)]=true};out:=make([]aoProposal,0,len(base));for _,c:=range base{p:=aoProposal{ID:"proposal-"+c.ID,Representation:c.Semantics,Semantics:c.Semantics,Signature:aoSig(t,c)};if c.Semantics=="UNBUILDABLE"{p.Terminal="REJECTED_GENERATION";p.Reason="candidate construction failed"}else if !aoVerify(t,c,probes){p.Terminal="REJECTED_VERIFICATION";p.Reason="independent reference execution failed"}else if baseS[p.Signature]{p.Terminal="REJECTED_SEMANTICS";p.Reason="behaviorally equivalent to frozen baseline on independent probes"}else{p.Terminal="ACCEPTED"};out=append(out,p)};return out}
func aoRun(name string,ps []aoProposal,target []ProgramTestCase,budget int)aoCondition{used:=0;installed:="";pass:=false;for _,p:=range ps{used++;if used>budget{break};if p.Terminal=="ACCEPTED"{installed=p.ID;var q UniversalProgram;if json.Unmarshal([]byte(p.Semantics),&q)==nil{ok:=true;for _,tc:=range target{o,e:=aoRef(q,tc.Input);if e!=nil{ok=false;break};for k,w:=range tc.Expected{if o[k]!=w{ok=false}}};if ok{pass=true}}}};return aoCondition{Name:name,Proposals:ps,Installed:installed,FutureSearchExposed:installed!=""&&!pass,HeldOut:pass,CandidateCount:len(ps),BudgetUsed:used}}

func TestAutonomousOperatorDiscovery(t *testing.T){h,p,gs,w,m:=aoProv(t);ts:=time.Now().UTC().Format(time.RFC3339Nano);s:=aoSpec(t);target:=aoTarget();base:=aoBase(t,s);probes:=append(aoExamples(),[]ProgramTestCase{{Input:map[string]string{"x":"-11"}},{Input:map[string]string{"x":"7"}},{Input:map[string]string{"x":"19"}}}...);k0:=vfEval("K0-baseline",base,target);props:=aoPropose(t,base,probes);kd:=aoRun("K-discovery",append([]aoProposal(nil),props...),target,20);koP:=append([]aoProposal(nil),props...);if len(koP)>1{koP[0],koP[1]=koP[1],koP[0]};ko:=aoRun("K-order",koP,target,20);krP:=append([]aoProposal(nil),props...);rand.New(rand.NewSource(20260911)).Shuffle(len(krP),func(i,j int){krP[i],krP[j]=krP[j],krP[i]});kr:=aoRun("K-random",krP,target,20);recomb:=aoRun("K-recombination",append([]aoProposal(nil),props...),target,20);rem:=aoCondition{Name:"discovered-operator-removed",Proposals:props,Installed:"",FutureSearchExposed:false,HeldOut:k0.HeldOut,CandidateCount:len(props)};class:="AUTONOMOUS_OPERATOR_DISCOVERY_NOT_DEMONSTRATED";boundary:="The current discovery path can only package candidates already expressible by the frozen baseline language; the independent behavioral novelty gate rejects them, so no genuinely new executable operator is autonomously installed.";if k0.HeldOut{class="RESULT_INVALID_OR_INCOMPLETE";boundary="K0 solved the external held-out target, eliminating the required causal gap."};r:=aoReport{Head:h,Parent:p,GitStatus:gs,ExperimentCommit:h,RuntimeTimestamp:ts,WorkflowRunID:w,ProvenanceMatch:m,Target:"external held-out integer mapping",GapDiagnosis:map[string]any{"gap_identified":!k0.HeldOut,"basis":"K0 failure on external held-out cases"},Conditions:[]aoCondition{kd,ko,recomb,kr,rem},NoveltyRule:map[string]any{"behavioral_equivalence_probes":len(probes),"syntax_not_counted":true,"novelty_requires_unmatched_behavior":true},IndependentVerification:map[string]any{"reference_path":"aoRef","self_certification":false,"verification_cases":len(probes)},Controls:map[string]any{"same_budget":true,"budget":20,"same_evaluator":true,"same_target_cases":len(target),"no_target_specific_primitive":true,"no_preinstalled_acquired_operator":true,"random_seed":20260911,"historical_fixtures_modified":false},Answers:map[string]any{"capability_gap_diagnosed":!k0.HeldOut,"autonomous_hypothesis_proposed":len(props)>0,"executable_candidate_constructed":len(props)>0,"independent_verification_performed":true,"novel_operator_discovered":false,"installation_occurred":kd.Installed!="","future_search_exposure":kd.FutureSearchExposed,"heldout_acquired":kd.HeldOut,"removal_restores_failure":!rem.HeldOut,"ordering_explanation":ko.HeldOut,"recombination_explanation":recomb.HeldOut,"random_explanation":kr.HeldOut},FinalClassification:class,ExactBoundary:boundary};b,e:=json.MarshalIndent(r,"","  ");if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join("..","..","ACE_AUTONOMOUS_OPERATOR_DISCOVERY.json"),append(b,'\n'),0644);e!=nil{t.Fatal(e)};md:=fmt.Sprintf("# ACE Autonomous Operator Discovery\n\nHEAD `%s`\nParent `%s`\nExperiment commit `%s`\nRuntime timestamp `%s`\nWorkflow run ID `%s`\nProvenance match: **%t**\nGit status: `%s`\n\nThe autonomous path receives generic observed examples; the external target exists only at the evaluation boundary.\n\n- K0 held-out: **%t**\n- Capability gap diagnosed: **%t**\n- Proposals: **%d**\n- Independent verification cases: **%d**\n- K-discovery installed: `%s`\n- K-discovery held-out: **%t**\n- K-order held-out: **%t**\n- K-recombination held-out: **%t**\n- K-random held-out: **%t**\n- Removal held-out: **%t**\n- Novel semantic operator discovered: **false**\n\nEvery proposal has a terminal classification; baseline-equivalent proposals are `REJECTED_SEMANTICS`.\n\nClassification: `%s`\n\nExact boundary: %s\n",h,p,h,ts,w,m,strings.ReplaceAll(gs,"\n","\\n"),k0.HeldOut,!k0.HeldOut,len(props),len(probes),kd.Installed,kd.HeldOut,ko.HeldOut,recomb.HeldOut,kr.HeldOut,rem.HeldOut,class,boundary);if e=os.WriteFile(filepath.Join("..","..","ACE_AUTONOMOUS_OPERATOR_DISCOVERY.md"),[]byte(md),0644);e!=nil{t.Fatal(e)}}
